import os
pat = b"invoice"

files = []
for root, dirs, names in os.walk("."):
    for nm in names:
        p = os.path.join(root, nm)
        if os.path.isfile(p) and not os.path.islink(p):
            files.append(p)
files.sort(key=lambda s: s.encode())

def count(path):
    n = 0
    counted = False
    carry = b""
    with open(path, "rb", buffering=0) as f:
        while True:
            chunk = f.read(1 << 22)
            if not chunk:
                break
            segs = (carry + chunk).split(b"\n")
            tail = segs.pop()
            for seg in segs:
                if not counted and pat in seg:
                    n += 1
                counted = False
            if pat in tail:
                counted = True
            carry = tail[-6:]
    return n

total = 0
